create or replace function app.list_investor_financial_report_summaries() returns table(report_id uuid,title text,period_type public.period_type,period_start date,period_end date,published_at timestamptz,revenue_total numeric,hpp_total numeric,gross_profit numeric,agent_fee_total numeric,partner_fee_total numeric,marketing_fee_total numeric,payment_fee_total numeric,operating_expense_total numeric,tax_expense_total numeric,other_expense_total numeric,expense_total numeric,net_profit numeric,gross_margin_percent numeric,net_margin_percent numeric) language sql stable security definer set search_path='' as $$select fr.id,fr.title,fp.period_type,fp.starts_on,fp.ends_on,fv.published_at,coalesce(max(li.amount) filter(where li.line_key='revenue_total'),0),coalesce(max(li.amount) filter(where li.line_key='hpp_total'),0),coalesce(max(li.amount) filter(where li.line_key='gross_profit'),0),coalesce(max(li.amount) filter(where li.line_key='agent_fee_total'),0),coalesce(max(li.amount) filter(where li.line_key='partner_fee_total'),0),coalesce(max(li.amount) filter(where li.line_key='marketing_fee_total'),0),coalesce(max(li.amount) filter(where li.line_key='payment_fee_total'),0),coalesce(max(li.amount) filter(where li.line_key='operating_expense_total'),0),coalesce(max(li.amount) filter(where li.line_key='tax_expense_total'),0),coalesce(max(li.amount) filter(where li.line_key='other_expense_total'),0),coalesce(max(li.amount) filter(where li.line_key='expense_total'),0),coalesce(max(li.amount) filter(where li.line_key='net_profit'),coalesce(max(li.amount) filter(where li.line_key='revenue_total'),0)-coalesce(max(li.amount) filter(where li.line_key='expense_total'),0)),coalesce(max(k.value) filter(where k.kpi_key='gross_margin_percent'),0),coalesce(max(k.value) filter(where k.kpi_key='net_margin_percent'),0) from public.financial_reports fr join public.financial_periods fp on fp.id=fr.financial_period_id join public.financial_report_versions fv on fv.id=fr.published_version_id and fv.financial_report_id=fr.id left join public.financial_line_items li on li.financial_report_version_id=fv.id left join public.financial_kpis k on k.financial_report_version_id=fv.id where app.current_investor_id() is not null and fr.status='published' and fr.visibility='investors' and fv.status='published' and fp.status in('closed','locked') group by fr.id,fr.title,fp.period_type,fp.starts_on,fp.ends_on,fv.published_at order by fp.ends_on desc,fr.created_at desc$$;revoke all on function app.list_investor_financial_report_summaries() from public,anon;grant execute on function app.list_investor_financial_report_summaries() to authenticated;